<template><section class="card"><h1>Welcome back</h1><form @submit.prevent="login"><input v-model="email" type="email" placeholder="Email" required/><input v-model="password" type="password" placeholder="Password" minlength="8" required/><button :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button><p v-if="error">{{error}}</p></form></section></template><script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{api}from'../services/api';const email=ref('');const password=ref('');const error=ref('');const busy=ref(false);const router=useRouter();async function login(){busy.value=true;error.value='';try{const r=await api.login(email.value,password.value);localStorage.setItem('accessToken',r.accessToken);router.push('/')}catch{error.value='Unable to sign in. Check your credentials.'}finally{busy.value=false}}</script>